-- food menu snapshots, batch 9 (16 menus)
with target as (
  select slug from venues where slug = 'lezat-beach-restaurant-at-ashyana-candidasa-beach-resort' and status = 'active' and publication_status = 'published'
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'Lezat Beach Restaurant Menu', 1, 'draft', 'partial', 'https://www.lezatbeachrestaurant.com/wp-content/uploads/2023/06/Reguler-Menu-2023_compressed.pdf', 'Official Lezat Beach Restaurant at Ashyana Candidasa Beach Resort menu',
         '2026-08-25T01:47:06+00:00'::timestamptz, null, '2026-11-23T01:47:06+00:00'::timestamptz, '2209f56484e55322ecdaee4bf645406904b0d310b14b01ec466e9230cf9a3388', 'food'
  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug and x.kind = 'food')
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
  select m.id, s.name, s.pos from m, (values ('Cooking Class', 0)) as s(name, pos)
  returning id, name
)
insert into menu_items (menu_id, section_id, name, description, price_minor, currency, position)
select m.id, secs.id, i.name, i.descr, i.price, i.cur, i.pos
from m, secs
join (values ('Cooking Class', 'Bumbu Bali (Paste Bumbu Bali)', 'Basic spices of Balinese Cooking', 650000, 'IDR', 0), ('Cooking Class', 'Lumpia Goreng (Fried Spring Roll)', 'Lightly fried served with fresh organic salad and home made sweet chili sauce', 625000, 'IDR', 1), ('Cooking Class', 'Tum Be Siap', 'Steamed slices of chicken with Balinese spicy wrapped with banana leaf', 600000, 'IDR', 2), ('Cooking Class', 'Tipat Cantok (Balinese Gado-Gado)', 'Balinese style gado-gado with tipat (soft rice in young coconut leaves), bean sprouts, fried tofu and rice cracker in spicy peanut sauce', 600000, 'IDR', 3), ('Cooking Class', 'Sate Lilit (Minced Fish Wrapped Around Skewer)', 'Fresh fish minced with Balinese spicy and coconut milk on lemon grass or bamboo stick', 600000, 'IDR', 4), ('Cooking Class', 'Pisang Goreng (Fried Banana)', 'Lightly fried battered golden banana served with grated coconut and palm sugar', 600000, 'IDR', 5)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

