with target as (
  select slug from venues where slug = 'lobby-bar-at-discovery-kartika-plaza-hotel' and status = 'active' and publication_status = 'published'
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'Cake and Bakery Menu', 1, 'draft', 'partial', 'https://www.discoverykartikaplaza.com/pdf/menus/lobby-bar/Food.pdf', 'Official Lobby Bar at Discovery Kartika Plaza Hotel menu',
         '2026-08-25T01:47:06+00:00'::timestamptz, null, '2026-11-23T01:47:06+00:00'::timestamptz, 'fe36fbdafebc0b8b2c6ab3aaf095847d1ceb9cf08d65f4dfe8b54710751853f4', 'food'
  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug and x.kind = 'food')
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
  select m.id, s.name, s.pos from m, (values ('Slice Cake', 0)) as s(name, pos)
  returning id, name
)
